// DeleteUniqueIndexCache 删除索引存在的缓存
func (o *OrderRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.Order) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, o.cache.Key(CacheOrderByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[o.cache.Key(CacheOrderByIDPrefix, item.ID)] = struct{}{}
			KeyMap[o.cache.Key(CacheOrderByOrderNumberPrefix, item.OrderNumber)] = struct{}{}
			KeyMap[o.cache.Key(CacheOrderByCertificateIDPrefix, item.CertificateID)] = struct{}{}
			KeyMap[o.cache.Key(CacheOrderByGoodIDPrefix, item.GoodID)] = struct{}{}
			KeyMap[o.cache.Key(CacheOrderByOriginOrderNumberPrefix, item.OriginOrderNumber)] = struct{}{}
			KeyMap[o.cache.Key(CacheOrderByPhPrefix, item.Ph)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := o.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
